head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDODS16500";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_nowVars();
        scwin.init_conds();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldods16500.onpageload' });
    }
};

/**
 * @method
 * @name init_nowVars
 * @description 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님)
 * @returns {void}
 * @hidden N
 */
scwin.init_nowVars = function () {
    const pc = $c.util.getComponent('dma_pageContext');
    if (!pc || !pc.set || !pc.get) { return; }
    if (!pc.get("today")) { pc.set("today", $c.date.getServerDateTime("yyyyMMdd")); }
};

/**
 * @method
 * @name init_conds
 * @description 표시 조건 평가 — 컨텍스트·세션 값에 따라 영역·버튼을 show/hide(진입 1회·데이터 재적재 시 재호출)
 * @returns {void}
 * @hidden N
 */
scwin.init_conds = function () {
    const binds = [{ id: "c_when_15", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1'); } }, { id: "c_when_17", fn: function(){ return ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '2'); } }, { id: "c_otherwise_19", fn: function(){ return (!(((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '1') || ((dma_session.get("spotIsuTrdMktTpCd") ?? (() => { throw new Error("unresolved:" + "session.company.spotIsuTrdMktTpCd"); })()) === '2'))); } }];
    binds.forEach(function (b) {
        const comp = $c.util.getComponent(b.id);
        if (!comp) { return; }
        let ok;
        // 조건식이 미해결 값(unresolved throw)을 읽는 자리는 그 바인드만 건너뛴다 — 공급사 산출의 바인드별 격리 유지
        try { ok = !!b.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); return; }
        if (ok) { comp.show(); } else { comp.hide(); }
        if (ok && b.grids) {
            b.grids.forEach(function (gid) {
                const gc = $c.util.getComponent(gid);
                if (gc && gc.refreshGridView) { gc.refreshGridView(); }
            });
        }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        await scwin.tab('list');

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_tab_onclick
 * @description 「목록」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_tab_onclick = async function(e){
    try {
        await scwin.tab('list')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.btn_tab_onclick' }); }
};

/**
 * @method
 * @name btn_tab_2_onclick
 * @description 「달력」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_tab_2_onclick = async function(e){
    try {
        await scwin.tab('cal')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.btn_tab_2_onclick' }); }
};

/**
 * @method
 * @name slc_year_onchange
 * @description slc_year 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.slc_year_onchange = async function(e){
    try {
        await scwin.yearChange()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.slc_year_onchange' }); }
};

/**
 * @method
 * @name btn_monthChange_onclick
 * @description btn_monthChange 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_monthChange_onclick = async function(e){
    try {
        await scwin.monthChange('' + dma_month.get("code") + '')

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldods16500.btn_monthChange_onclick' }); }
};

/**
 * @method
 * @name btn_window_onclick
 * @description 「레이어닫기」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_window_onclick = function(e){
    try {
        $c.win.closePopup()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldods16500.btn_window_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_search_ajaxsubmit
 * @description search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_search_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fn_search_ajaxsubmit",
        method: "post",
        action: "/sprtroom/schedule.do",
        ref: "dma_searchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tab
 * @description tab 처리
 * @param {*} ipt_displayDiv ipt_displayDiv
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tab = async function (ipt_displayDiv) {
    $('#ipt_displayDiv', $('#searchForm')).val(ipt_displayDiv);
    await scwin.search();
};

/**
 * @method
 * @name yearChange
 * @description year Change 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.yearChange = async function () {
    await scwin.search();
};

/**
 * @method
 * @name monthChange
 * @description month Change 처리
 * @param {*} ipt_month ipt_month
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.monthChange = async function (ipt_month) {
    $("#monthListArea").children("a").each(function(i) {
            $(this).removeClass();
            if ((i + 1) === Number(ipt_month)) {
                $(this).addClass("active");
            }
    });
    $('#ipt_month', $('#searchForm')).val(ipt_month);
    await scwin.search();
};

/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function () {
    $('#ipt_SCREN_ID', $('#searchForm')).val("/ui/jsp/JLDODS16500.xml");
    $('#ipt_method', $('#searchForm')).val("findDisclosureSchedules");
    await scwin.tx_fn_search_ajaxsubmit();
};

/**
 * @method
 * @name searchCallBack
 * @description search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.searchCallBack = function (data) {
    if ($('#ipt_displayDiv', $('#searchForm')).val() === "list") {
        $("#cal_list", $('#searchForm')).empty().html(data).trigger("create");
    } else {
        $("#cal_view", $('#searchForm')).empty().html(data).trigger("create");
    }
};

/**
 * @method
 * @name findSchedule1
 * @description find Schedule1 처리
 * @param {String} ipt_calndDd ipt_calndDd
 * @param {*} ipt_byddSeq ipt_byddSeq
 * @returns {void}
 * @hidden N
 */
scwin.findSchedule1 = function (ipt_calndDd, ipt_byddSeq) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const disclosureSchedulePop = $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/sprtroom/schedule.do?method=findDisclosureSchedule1&calndDd=" + ipt_calndDd + "&byddSeq=" + ipt_byddSeq + ""), { id: "공시일정상세", scrollbars: false, width: "500", height: "320", resizable: true, type: "pageFramePopup" }, {});
};

/**
 * @method
 * @name findSchedule2
 * @description find Schedule2 처리
 * @param {*} ipt_acptNo ipt_acptNo
 * @param {String} ipt_schdlAdmItmTpCd ipt_schdlAdmItmTpCd
 * @param {*} ipt_byddSeq ipt_byddSeq
 * @returns {void}
 * @hidden N
 */
scwin.findSchedule2 = function (ipt_acptNo, ipt_schdlAdmItmTpCd, ipt_byddSeq) {
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const disclosureSchedulePop = $c.win.openPopup((function (__u) { let __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })("/sprtroom/schedule.do?method=findDisclosureSchedule2&acptNo=" + ipt_acptNo + "&schdlAdmItmTpCd=" + ipt_schdlAdmItmTpCd + "&byddSeq=" + ipt_byddSeq + ""), { id: "공시일정상세", scrollbars: false, width: "500", height: "350", resizable: true, type: "pageFramePopup" }, {});
};
